<script setup>defineProps({events:{type:Array,default:()=>[]}});const status=s=>({running:'执行中',completed:'已完成',failed:'失败'}[s]||s)</script><template><section v-if="events.length" class="trace-panel"><h2>本次执行记录</h2><details v-for="event in events" :key="event.id" :open="event.status==='running'"><summary>{{status(event.status)}} · {{event.name}} <span v-if="event.durationMs!==undefined">{{event.durationMs}} ms</span></summary><pre v-if="event.arguments">参数：{{event.arguments}}</pre><pre v-if="event.result">{{event.result}}</pre><article v-for="(s,i) in event.sources||[]" :key="i"><strong>[资料{{i+1}}] {{s.source}}</strong><small>相似度 {{Number(s.score).toFixed(3)}}</small><p>{{s.content}}</p></article><p v-if="event.sources?.length===0">没有找到相关资料</p></details></section></template><style scoped>.trace-panel{margin:10px 20px;padding:16px 20px;background:#f4f8fa;border:1px solid #dce5eb;border-radius:10px;color:#344e60;max-height:320px;overflow:auto}.trace-panel h2{font-size:14px;margin-bottom:12px}.trace-panel details{font-size:13px;margin:10px 0}.trace-panel summary{cursor:pointer}.trace-panel summary span{color:#728593;margin-left:12px}.trace-panel pre,.trace-panel p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.6;font-size:12px;margin-top:10px}.trace-panel article{border-left:2px solid #6db4a7;padding-left:12px;margin:15px 0}.trace-panel small{display:block;margin-top:5px}</style>